def algorithm(func, dim, lb, ub, budget, rng):
    def sample_gaussian(mean, cov, rng=rng):
        return mean + rng.normal(size=(dim,), loc=0., scale=np.sqrt(np.diag(cov)))

    def recombination(x1, x2, w):
        return (x1 * w) + (x2 * (1 - w))

    def polynomial_mutation(x, mut_pow, delta, rng=rng):
        delta_p = np.multiply(delta, rng.normal(size=(dim,), loc=0., scale=np.sqrt(np.diag(delta))))
        mutate = np.power(1.0 + delta_p, mut_pow) - 1
        return (1.0 + mutate) * x

    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    # Initial parameters
    mean = np.zeros(dim)
    cov = np.eye(dim) * 10000
    w = 10 / dim
    delta = np.ones(dim) * 0.1
    mut_pow = 20

    for _ in range(budget):
        # Sample from multivariate normal distribution
        x = sample_gaussian(mean, cov)

        # Clip to bounds
        x = clip(x, lb, ub)

        # Evaluate function
        fx = func(x)
        if fx < 0:
            mean = x
            cov = np.eye(dim) * 10000

        # Recombination and mutation
        xm = recombination(mean, x, w)
        xp = polynomial_mutation(xm, mut_pow, delta)

        # Clip to bounds
        xp = clip(xp, lb, ub)

        # Evaluate function
        fxp = func(xp)
        if fxp < fx:
            mean = (mean * (1 - w)) + (xp * w)
            cov = 0.5 * ((cov + np.outer((x - mean), (x - mean))) / (1 - w) +
                         (cov + np.outer((xp - mean), (xp - mean))) / w)

    # Return the best solution found
    return clip(mean, lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    best_candidate = rng.uniform(lb, ub, size=dim)
    best_value = func(clip(best_candidate))

    for _ in range(budget - 1):
        midpoint = (lb + ub) / 2
        candidate = np.zeros(dim)
        for i in range(dim):
            if rng.random() < 0.5:
                candidate[i] = lb + (ub - lb) * rng.uniform(0, 1)
            else:
                candidate[i] = midpoint + (ub - lb) / 2 * rng.uniform(-1, 1)

        candidate = clip(candidate)
        value = func(candidate)

        if value < best_value:
            best_candidate = candidate
            best_value = value

    return best_candidate

